static bool Ok(sl::Result r){return r==sl::Result::eOk;}
static sl::float4x4 Identity(){sl::float4x4 m{};m[0]={1,0,0,0};m[1]={0,1,0,0};m[2]={0,0,1,0};m[3]={0,0,0,1};return m;}
StreamlineDLSS::~StreamlineDLSS(){Shutdown();}
