HRESULT StreamlineDLSS::CreateFactory(UINT flags,REFIID interfaceId,void** factory)const{return framework_&&api_?api_->createFactory(flags,interfaceId,factory):CreateDXGIFactory2(flags,interfaceId,factory);}
HRESULT StreamlineDLSS::CreateDevice(IUnknown* adapter,D3D_FEATURE_LEVEL featureLevel,REFIID interfaceId,void** device)const{return framework_&&api_?api_->createDevice(adapter,featureLevel,interfaceId,device):D3D12CreateDevice(adapter,featureLevel,interfaceId,device);}
