bool StreamlineDLSS::ValidateOutput(){if(!Enabled()||outputValidated_||!validationReadback_)return true;unsigned char* pixel{};D3D12_RANGE read{0,4};if(SUCCEEDED(validationReadback_->Map(0,&read,reinterpret_cast<void**>(&pixel)))){bool black=!pixel[0]&&!pixel[1]&&!pixel[2]&&!pixel[3];D3D12_RANGE written{0,0};validationReadback_->Unmap(0,&written);if(black){if(++blackFrames_>=3){enabled_=false;reset_=true;ReleaseResources();}}else outputValidated_=true;}return !Enabled()||outputValidated_;}
